import client from "./client.js";

export const getDashboard = (days = 7) => client.get("/dashboard", { params: { days } }).then((r) => r.data);

// Guests see clearly labelled demo data generated by the backend (never stored).
export const getDemoDashboard = (days = 7) => client.get("/demo/dashboard", { params: { days } }).then((r) => r.data);
